// Netscape bookmark HTML import/export (spec FR-026/FR-027, research §8).
// Preserves title, tags (TAGS attribute + enclosing folder H3 names), and ADD_DATE.
import { parse as parseHtml } from 'node-html-parser';

// Parse a Netscape bookmark file into a flat list of entries.
// Returns [{ url, title, tags: string[], addDate: number|null }]
export function parseNetscape(html) {
  const root = parseHtml(html, { blockTextElements: {} });
  const entries = [];

  // Walk DL/DT structure, tracking folder (H3) names as tag context.
  function walk(node, folderStack) {
    const children = node.childNodes || [];
    for (let i = 0; i < children.length; i++) {
      const child = children[i];
      if (child.nodeType !== 1) continue; // element nodes only
      const tag = child.rawTagName ? child.rawTagName.toLowerCase() : '';
      if (tag === 'dt') {
        const h3 = child.querySelector('h3');
        const a = child.querySelector('a');
        if (h3) {
          const folderName = h3.text.trim();
          const nextFolders = folderName ? [...folderStack, folderName] : folderStack;
          // The nested <DL> may be a sibling of this DT or a child.
          const dl = child.querySelector('dl') || findFollowingDl(children, i);
          if (dl) walk(dl, nextFolders);
        } else if (a) {
          const url = a.getAttribute('href');
          if (!url) continue;
          const title = a.text.trim() || url;
          const addDateAttr = a.getAttribute('add_date') || a.getAttribute('ADD_DATE');
          const addDate = addDateAttr ? parseInt(addDateAttr, 10) : null;
