        </div>
      </div>
    );
  }

  function set(field, val) { setBm({ ...bm, [field]: val }); }

  async function save() {
    setBusy(true); setErr('');
    try {
      const r = await api.updateBookmark(id, {
        url: bm.url, title: bm.title, description: bm.description,
        note: bm.note, tags: bm.tags
      });
      setBm(r.bookmark);
      onSaved && onSaved();
    } catch (e) {
      setErr(e.message);
    } finally {
      setBusy(false);
    }
  }

  async function preserve(kind) {
