// Netscape bookmark HTML import/export (spec FR-026/FR-027, research §8).
// Preserves title, tags (TAGS attribute + enclosing folder H3 names), and ADD_DATE.
import { parse as parseHtml } from 'node-html-parser';

// Parse a Netscape bookmark file into a flat list of entries.
// Returns [{ url, title, tags: string[], addDate: number|null }]
export function parseNetscape(html) {
  const root = parseHtml(html, { blockTextElements: {} });
  const entries = [];

  // Walk DL/DT structure, tracking folder (H3) names as tag context.
  function walk(node, folderStack) {
    const children = node.childNodes || [];
    for (let i = 0; i < children.length; i++) {
      const child = children[i];
      if (child.nodeType !== 1) continue; // element nodes only
      const tag = child.rawTagName ? child.rawTagName.toLowerCase() : '';
      if (tag === 'dt') {
        const h3 = child.querySelector('h3');
        const a = child.querySelector('a');
        if (h3) {
          const folderName = h3.text.trim();
          const nextFolders = folderName ? [...folderStack, folderName] : folderStack;
          // The nested <DL> may be a sibling of this DT or a child.
          const dl = child.querySelector('dl') || findFollowingDl(children, i);
          if (dl) walk(dl, nextFolders);
        } else if (a) {
          const url = a.getAttribute('href');
          if (!url) continue;
          const title = a.text.trim() || url;
          const addDateAttr = a.getAttribute('add_date') || a.getAttribute('ADD_DATE');
          const addDate = addDateAttr ? parseInt(addDateAttr, 10) : null;
          const tagsAttr = a.getAttribute('tags') || a.getAttribute('TAGS');
          const tags = new Set(folderStack);
          if (tagsAttr) {
            tagsAttr.split(',').map(t => t.trim()).filter(Boolean).forEach(t => tags.add(t));
          }
          entries.push({
            url,
            title,
            tags: [...tags],
            addDate: Number.isFinite(addDate) ? addDate : null
          });
        }
      } else if (tag === 'dl' || tag === 'p') {
        walk(child, folderStack);
      }
    }
  }

  function findFollowingDl(siblings, fromIndex) {
    for (let k = fromIndex + 1; k < siblings.length; k++) {
      const s = siblings[k];
      if (s.nodeType === 1 && s.rawTagName && s.rawTagName.toLowerCase() === 'dl') return s;
    }
    return null;
  }

  const topDl = root.querySelector('dl') || root;
  walk(topDl, []);
  return entries;
}

// Serialize bookmarks to a Netscape bookmark HTML file.
// bookmarks: [{ url, title, tags: string[], created_at: ms }]
export function serializeNetscape(bookmarks) {
  const lines = [];
  lines.push('<!DOCTYPE NETSCAPE-Bookmark-file-1>');
  lines.push('<!-- This is an automatically generated file. -->');
  lines.push('<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">');
  lines.push('<TITLE>Bookmarks</TITLE>');
  lines.push('<H1>Bookmarks</H1>');
  lines.push('<DL><p>');
  for (const b of bookmarks) {
    const addDate = b.created_at ? Math.floor(b.created_at / 1000) : Math.floor(Date.now() / 1000);
    const tags = (b.tags && b.tags.length) ? ` TAGS="${escapeAttr(b.tags.join(','))}"` : '';
    lines.push(
      `    <DT><A HREF="${escapeAttr(b.url)}" ADD_DATE="${addDate}"${tags}>${escapeText(b.title || b.url)}</A>`
    );
  }
  lines.push('</DL><p>');
  return lines.join('\n') + '\n';
}

function escapeAttr(s) {
  return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}
function escapeText(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

