    res.json({
      duplicate: false,
      metadata: {
        title: meta.title || titleFromUrl(url),
        description: meta.description || '',
        icon_url: meta.icon_url || null,
        preview_image_url: meta.preview_image_url || null,
        metadata_status: meta.status || 'ok'
      }
    });
  } catch (err) {
    next(err);
  }
